// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, uint256 delta) public {
        vm.assume(t1 > 1);
        vm.assume(delta <= 1); // admissible second-call times: t1 (same time) or t1+1 (stored value t1+1)
        vm.assume(t1 + delta < type(uint256).max);

        address actor = address(0xABCD);
        vm.deal(actor, 20 ether);

        // first call at time t1 (must succeed on both versions)
        vm.warp(t1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // second call at time t1 + delta, delta in {0,1}: guard forbids it on reference
        vm.warp(t1 + delta);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // general rule: any second fallback call at ts <= pastBlockTime (t1+1) must revert
        assertTrue(!ok2, "second call within guard window must revert");
    }
}
